<?php
namespace App\Http\Controllers\Api\V1;
use App\Contracts\OtpSender; use App\Http\Controllers\Controller; use App\Models\User; use App\Models\UserApprovalRequest; use App\Models\VerificationChallenge; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Str;
class VerificationController extends Controller
{
 public function send(Request $request, User $user, OtpSender $sender): JsonResponse { $data=$request->validate(['channel'=>'required|in:email,sms']);$channel=$data['channel'];$hash=$channel==='email'?$user->email_hash:$user->phone_hash;$destination=Crypt::decryptString($channel==='email'?$user->email_encrypted:$user->phone_encrypted);VerificationChallenge::where(['user_id'=>$user->id,'channel'=>$channel,'purpose'=>'registration','status'=>'pending'])->update(['status'=>'invalidated','invalidated_at'=>now()]);$otp=(string)random_int(100000,999999);VerificationChallenge::create(['public_id'=>(string)Str::ulid(),'user_id'=>$user->id,'channel'=>$channel,'purpose'=>'registration','destination_hash'=>$hash,'otp_hash'=>Hash::make($otp),'status'=>'pending','expires_at'=>now()->addMinutes(config('ai_lms.otp.ttl_minutes')),'maximum_attempts'=>config('ai_lms.otp.max_attempts'),'last_sent_at'=>now(),'request_ip'=>$request->ip()]);$sender->send($channel,$destination,$otp,'registration');return response()->json(['message'=>'Verification code sent.']); }
 public function verify(Request $request, User $user): JsonResponse { $data=$request->validate(['channel'=>'required|in:email,sms','otp'=>'required|digits:6']);$challenge=VerificationChallenge::where(['user_id'=>$user->id,'channel'=>$data['channel'],'purpose'=>'registration','status'=>'pending'])->latest()->firstOrFail();abort_if($challenge->expires_at->isPast(),422,'Verification code expired.');$challenge->increment('attempt_count');abort_if($challenge->attempt_count>$challenge->maximum_attempts,429,'Too many attempts.');abort_unless(Hash::check($data['otp'],$challenge->otp_hash),422,'Invalid verification code.');$challenge->update(['status'=>'verified','verified_at'=>now()]);$verifiedColumn=$data['channel']==='email'?'email_verified_at':'phone_verified_at';$user->forceFill([$verifiedColumn=>now()])->save();if($user->email_verified_at&&$user->phone_verified_at){$user->update(['status'=>'pending_approval','registration_completed_at'=>now()]);UserApprovalRequest::firstOrCreate(['subject_user_id'=>$user->id,'status'=>'pending'],['public_id'=>(string)Str::ulid(),'requested_by'=>$user->created_by,'required_approver_level'=>'super_admin','submitted_at'=>now()]);}return response()->json(['data'=>$user->refresh()]); }
}
